package com.rork.vitahero.data

import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Paint
import android.graphics.Typeface
import android.graphics.pdf.PdfDocument
import android.net.Uri
import android.os.Environment
import androidx.core.content.FileProvider
import java.io.File
import java.io.FileOutputStream
import java.time.LocalDate
import java.time.format.DateTimeFormatter

data class ReportData(
    val kid: Kid,
    val meals: List<MealItem>,
    val streak: StreakInfo,
    val badges: List<Badge>,
    val generatedDate: String = LocalDate.now().format(DateTimeFormatter.ofPattern("dd MMM yyyy"))
)

object PdfReportGenerator {

    private const val PAGE_WIDTH = 595
    private const val PAGE_HEIGHT = 842
    private const val MARGIN = 40
    private const val CONTENT_WIDTH = PAGE_WIDTH - MARGIN * 2
    private val dateFmt = DateTimeFormatter.ofPattern("dd MMM yyyy")

    fun generate(context: Context, data: ReportData): File {
        val document = PdfDocument()
        val page = document.startPage(
            PdfDocument.PageInfo.Builder(PAGE_WIDTH, PAGE_HEIGHT, 1).create()
        )
        val canvas = page.canvas

        val titlePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT_BOLD; textSize = 24f; color = 0xFF10B981.toInt()
        }
        val subtitlePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT_BOLD; textSize = 16f; color = 0xFF0F172A.toInt()
        }
        val bodyPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT; textSize = 12f; color = 0xFF475569.toInt()
        }
        val headerPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT_BOLD; textSize = 13f; color = 0xFF0F172A.toInt()
        }
        val greenPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT_BOLD; textSize = 12f; color = 0xFF10B981.toInt()
        }
        val alertPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT_BOLD; textSize = 12f; color = 0xFFEF4444.toInt()
        }
        val warnPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT_BOLD; textSize = 12f; color = 0xFFF59E0B.toInt()
        }
        val linePaint = Paint().apply {
            color = 0xFFE6EEEA.toInt(); strokeWidth = 1f
        }
        val bgPaint = Paint().apply {
            color = 0xFFF6FBF9.toInt(); style = Paint.Style.FILL
        }
        val whitePaint = Paint().apply {
            color = 0xFFFFFFFF.toInt(); style = Paint.Style.FILL
        }

        var y = MARGIN.toFloat()

        // Header
        canvas.drawRect(0f, 0f, PAGE_WIDTH.toFloat(), 100f, Paint().apply { color = 0xFF10B981.toInt() })
        canvas.drawText("VitaHero", MARGIN.toFloat(), 50f, Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT_BOLD; textSize = 28f; color = 0xFFFFFFFF.toInt()
        })
        canvas.drawText("Child Health Report", MARGIN.toFloat(), 78f, Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT; textSize = 14f; color = 0xD9FFFFFF.toInt()
        })
        y = 120f

        val k = data.kid

        // Kid info section
        canvas.drawText(k.name.uppercase(), MARGIN.toFloat(), y, titlePaint)
        y += 30f
        canvas.drawText("${k.age} yrs · ${k.gender} · ${k.school} · ${k.grade}", MARGIN.toFloat(), y, bodyPaint)
        y += 24f
        canvas.drawText("Report generated: ${data.generatedDate}", MARGIN.toFloat(), y, Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT; textSize = 10f; color = 0xFF94A3B8.toInt()
        })
        y += 36f

        // Vital stats card
        canvas.drawRoundRect(MARGIN.toFloat(), y, PAGE_WIDTH - MARGIN.toFloat(), y + 80f, 12f, 12f, bgPaint)
        y += 20f
        canvas.drawText("VITAL STATISTICS", MARGIN + 16f, y, headerPaint)
        y += 22f
        val stats = listOf(
            "Height" to "${k.heightCm.toInt()} cm",
            "Weight" to "${k.weightKg.toInt()} kg",
            "BMI" to "%.1f".format(k.bmi),
            "Health Score" to "${k.overallScore}%"
        )
        var sx = MARGIN + 16f
        stats.forEach { (label, value) ->
            canvas.drawText(label, sx, y, Paint(Paint.ANTI_ALIAS_FLAG).apply {
                typeface = Typeface.DEFAULT; textSize = 10f; color = 0xFF94A3B8.toInt()
            })
            canvas.drawText(value, sx, y + 14f, Paint(Paint.ANTI_ALIAS_FLAG).apply {
                typeface = Typeface.DEFAULT_BOLD; textSize = 16f; color = 0xFF0F172A.toInt()
            })
            sx += (CONTENT_WIDTH - 32f) / 4
        }
        y += 100f

        // Growth section
        canvas.drawText("GROWTH TRACKING", MARGIN.toFloat(), y, subtitlePaint)
        y += 24f
        drawGrowthChart(canvas, MARGIN.toFloat(), y, CONTENT_WIDTH.toFloat(), 120f, k.growth, false, 0xFF10B981.toInt())
        y += 130f
        drawGrowthChart(canvas, MARGIN.toFloat(), y, CONTENT_WIDTH.toFloat(), 120f, k.growth, true, 0xFF2563EB.toInt())
        y += 140f

        // Health flags
        canvas.drawText("HEALTH STATUS", MARGIN.toFloat(), y, subtitlePaint)
        y += 24f
        val flags = listOf(
            Triple("Dental", k.dental.label, k.dental),
            Triple("Eyesight", k.eyesight.label, k.eyesight),
            Triple("Nutrition", k.nutrition.label, k.nutrition)
        )
        flags.forEach { (name, label, flag) ->
            val fp = when (flag) { HealthFlag.GOOD -> greenPaint; HealthFlag.ALERT -> alertPaint; HealthFlag.WATCH -> warnPaint }
            canvas.drawText("$name: $label", MARGIN + 4f, y, fp)
            y += 20f
        }
        y += 10f

        // Badges
        canvas.drawText("EARNED BADGES", MARGIN.toFloat(), y, subtitlePaint)
        y += 24f
        val earned = data.badges.filter { it.earned }
        if (earned.isNotEmpty()) {
            earned.forEach { badge ->
                canvas.drawText("• ${badge.title} — ${badge.description}", MARGIN + 4f, y, bodyPaint)
                y += 18f
            }
        } else {
            canvas.drawText("No badges earned yet. Keep tracking meals!", MARGIN + 4f, y, bodyPaint)
            y += 18f
        }
        y += 10f

        // Diet summary
        canvas.drawText("DIET SUMMARY", MARGIN.toFloat(), y, subtitlePaint)
        y += 24f
        val eaten = data.meals.count { it.eaten }
        val totalKcal = data.meals.filter { it.eaten }.sumOf { it.kcal }
        canvas.drawText("Meals logged: $eaten / ${data.meals.size}", MARGIN + 4f, y, bodyPaint)
        y += 18f
        canvas.drawText("Calories consumed: $totalKcal kcal", MARGIN + 4f, y, bodyPaint)
        y += 18f
        canvas.drawText("Current streak: ${data.streak.currentStreak} days (Best: ${data.streak.bestStreak})", MARGIN + 4f, y, bodyPaint)
        y += 30f

        // Disclaimer
        canvas.drawLine(MARGIN.toFloat(), y, PAGE_WIDTH - MARGIN.toFloat(), y, linePaint)
        y += 16f
        canvas.drawText(
            "Disclaimer: This report is for informational purposes only. Always consult a qualified doctor for medical diagnosis and treatment.",
            MARGIN.toFloat(), y, Paint(Paint.ANTI_ALIAS_FLAG).apply {
                typeface = Typeface.DEFAULT; textSize = 9f; color = 0xFF94A3B8.toInt()
            }
        )

        document.finishPage(page)

        val dir = File(context.cacheDir, "reports")
        dir.mkdirs()
        val file = File(dir, "VitaHero_${k.name}_${LocalDate.now().format(DateTimeFormatter.BASIC_ISO_DATE)}.pdf")
        FileOutputStream(file).use { document.writeTo(it) }
        document.close()
        return file
    }

    private fun drawGrowthChart(
        canvas: Canvas,
        x: Float, y: Float, w: Float, h: Float,
        points: List<GrowthPoint>,
        weight: Boolean,
        color: Int
    ) {
        if (points.size < 2) return
        val values = points.map { if (weight) it.weight else it.height }
        val minV = values.min()
        val maxV = values.max()
        val range = (maxV - minV).coerceAtLeast(1f)
        val pad = 24f
        val chartW = w - pad * 2
        val chartH = h - pad * 2
        val stepX = chartW / (points.size - 1)

        val label = if (weight) "Weight (kg)" else "Height (cm)"
        val labelPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT_BOLD; textSize = 11f; color = color
        }
        canvas.drawText(label, x, y - 6f, labelPaint)

        val gridPaint = Paint().apply { this.color = 0x1A000000; strokeWidth = 1f }
        val linePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            this.color = color; strokeWidth = 4f; style = Paint.Style.STROKE; strokeCap = Paint.Cap.ROUND
        }
        val dotPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            this.color = 0xFFFFFFFF.toInt(); style = Paint.Style.FILL
        }
        val dotBorder = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            this.color = color; strokeWidth = 3f; style = Paint.Style.STROKE
        }

        // Grid
        for (i in 0..3) {
            val gy = y + pad + chartH * i / 3
            canvas.drawLine(x + pad, gy, x + pad + chartW, gy, gridPaint)
        }

        // Line
        for (i in 0 until points.size - 1) {
            val x1 = x + pad + stepX * i
            val y1 = y + pad + chartH - chartH * (values[i] - minV) / range
            val x2 = x + pad + stepX * (i + 1)
            val y2 = y + pad + chartH - chartH * (values[i + 1] - minV) / range
            canvas.drawLine(x1, y1, x2, y2, linePaint)
        }

        // Dots + labels
        val valPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            typeface = Typeface.DEFAULT; textSize = 9f; color = 0xFF0F172A.toInt()
        }
        points.forEachIndexed { i, pt ->
            val cx = x + pad + stepX * i
            val cy = y + pad + chartH - chartH * (values[i] - minV) / range
            canvas.drawCircle(cx, cy, 5f, dotPaint)
            canvas.drawCircle(cx, cy, 5f, dotBorder)
            canvas.drawText(
                if (weight) "${pt.weight}kg" else "${pt.height}cm",
                cx - 14f, cy - 10f, valPaint
            )
        }
    }

    fun shareReport(context: Context, file: File) {
        val uri = FileProvider.getUriForFile(
            context,
            "${context.packageName}.fileprovider",
            file
        )
        val intent = Intent(Intent.ACTION_SEND).apply {
            type = "application/pdf"
            putExtra(Intent.EXTRA_STREAM, uri)
            putExtra(Intent.EXTRA_SUBJECT, "VitaHero Health Report - ${file.nameWithoutExtension}")
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
        context.startActivity(Intent.createChooser(intent, "Share Health Report"))
    }
}

